window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-c7d55188a77f148a"]={"versions": [{"id": "FIG-c7d55188a77f148a", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des internen Teilablaufs „Read Length“ innerhalb der Prüffunktion <code>E2E_P04mCheck()</code> des AUTOSAR E2E-Profils 4m (End-to-End Communication Protection Profile 4m). Das Diagramm konkretisiert die funktionale Sequenz zur Längenextraktion auf Empfängerseite (Client- und Serverseite).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Aktivitätskontext:</strong> Funktion <code>E2E_P04mCheck()</code> (als referenzierte Aktivität/Verschachtelung oben links annotiert).\n</li><li><strong>Startknoten:</strong> Initialer Pseudo-Zustand (Initial Node).\n</li><li><strong>Aktionsknoten:</strong> Ausführungsschritt <code>Copy bytes Data[Offset...Offset+1] in Big Endian order to uint16 local variable ReceivedLength</code>.\n</li><li><strong>Endknoten:</strong> Aktivitätsendknoten (Activity Final Node).\n</li><li><strong>Kommentar/Notiz:</strong> <code>Options is always at the same location.</code>, über eine gestrichelte Abhängigkeitslinie an die Kopieraktion angebunden.\n</li><li><strong>Variablen und Parameter:</strong> Eingabearray <code>Data[]</code>, Konfigurations-/Offsetparameter <code>Offset</code>, lokale Zielvariable <code>ReceivedLength</code> vom Datentyp <code>uint16</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Die Aktivität beginnt am Startknoten.\n</li><li>Der Kontrollfluss führt direkt zur Aktion zur Datenextraktion: Zwei aufeinanderfolgende Bytes an der Position <code>Offset</code> und <code>Offset+1</code> aus dem Puffer <code>Data</code> werden in Big-Endian-Byte-Reihenfolge (Most Significant Byte zuerst) in die lokale 16-Bit-Variable <code>ReceivedLength</code> (<code>uint16</code>) eingelesen.\n</li><li>Nach Abschluss des Lesevorgangs erreicht der Kontrollfluss unmittelbar den Endknoten der Teilaktivität.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Gemäß Anforderung <code>[PRS_E2E_00774]</code> ist das dargestellte Verhalten für die Implementierung der Empfängerprüfung <code>E2E_P04mCheck()</code> sowohl auf Client- als auch auf Serverseite normativ verbindlich.\n</li><li>Bei der Extraktion von <code>ReceivedLength</code> muss zwingend die Big-Endian-Interpretation der beiden Datenbytes <code>Data[Offset]</code> und <code>Data[Offset+1]</code> beachtet werden, unabhängig von der nativen Plattform-Endianness der Host-Architektur.\n</li><li>Es ist sicherzustellen, dass das Datenarray <code>Data</code> mindestens die Länge <code>Offset + 2</code> aufweist, um Out-of-Bounds-Zugriffe vor Ausführung der Kopieroperation abzufangen.\n</li></ul>"}, {"id": "FIG-c8d06c46ad2dad9b", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des internen Teilablaufs „Read Length“ innerhalb der Prüffunktion <code>E2E_P04mCheck()</code> des AUTOSAR E2E-Profils 4m (End-to-End Communication Protection Profile 4m). Das Diagramm konkretisiert die funktionale Sequenz zur Längenextraktion auf Empfängerseite (Client- und Serverseite).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Aktivitätskontext:</strong> Funktion <code>E2E_P04mCheck()</code> (als referenzierte Aktivität/Verschachtelung oben links annotiert).\n</li><li><strong>Startknoten:</strong> Initialer Pseudo-Zustand (Initial Node).\n</li><li><strong>Aktionsknoten:</strong> Ausführungsschritt <code>Copy bytes Data[Offset...Offset+1] in Big Endian order to uint16 local variable ReceivedLength</code>.\n</li><li><strong>Endknoten:</strong> Aktivitätsendknoten (Activity Final Node).\n</li><li><strong>Kommentar/Notiz:</strong> <code>Options is always at the same location.</code>, über eine gestrichelte Abhängigkeitslinie an die Kopieraktion angebunden.\n</li><li><strong>Variablen und Parameter:</strong> Eingabearray <code>Data[]</code>, Konfigurations-/Offsetparameter <code>Offset</code>, lokale Zielvariable <code>ReceivedLength</code> vom Datentyp <code>uint16</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Die Aktivität beginnt am Startknoten.\n</li><li>Der Kontrollfluss führt direkt zur Aktion zur Datenextraktion: Zwei aufeinanderfolgende Bytes an der Position <code>Offset</code> und <code>Offset+1</code> aus dem Puffer <code>Data</code> werden in Big-Endian-Byte-Reihenfolge (Most Significant Byte zuerst) in die lokale 16-Bit-Variable <code>ReceivedLength</code> (<code>uint16</code>) eingelesen.\n</li><li>Nach Abschluss des Lesevorgangs erreicht der Kontrollfluss unmittelbar den Endknoten der Teilaktivität.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Gemäß Anforderung <code>[PRS_E2E_00774]</code> ist das dargestellte Verhalten für die Implementierung der Empfängerprüfung <code>E2E_P04mCheck()</code> sowohl auf Client- als auch auf Serverseite normativ verbindlich.\n</li><li>Bei der Extraktion von <code>ReceivedLength</code> muss zwingend die Big-Endian-Interpretation der beiden Datenbytes <code>Data[Offset]</code> und <code>Data[Offset+1]</code> beachtet werden, unabhängig von der nativen Plattform-Endianness der Host-Architektur.\n</li><li>Es ist sicherzustellen, dass das Datenarray <code>Data</code> mindestens die Länge <code>Offset + 2</code> aufweist, um Out-of-Bounds-Zugriffe vor Ausführung der Kopieroperation abzufangen.\n</li></ul>"}], "trans": [{"from": "FIG-c7d55188a77f148a", "to": "FIG-c8d06c46ad2dad9b", "fr": "R20-11", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
